-- Streamlined SSI Diver Medical (staff review, over-45, boxes A–G, dental)
UPDATE form_templates
SET schema_json = '{"key":"diver_medical","consent":{"required":true,"version":"dm-v3-staff","text":{"en":"Scuba diving needs good physical health. Answer honestly. If pregnant, do not dive. Yes on questions 3, 5, or 10 — or any follow-up box — flags your form for Banana Nut Burger Dive Shop staff review. You can always submit; staff review never blocks this form.","es":"El buceo requiere buena salud física. Responde con honestidad. Si está embarazada, no bucee. Sí en las preguntas 3, 5 o 10 — o cualquier casilla de seguimiento — marca tu formulario para revisión del personal de Banana Nut Burger Dive Shop. Siempre puedes enviar; la revisión nunca bloquea este formulario."}},"sections":[{"id":"dm_main","title":{"en":"Part 1 — General health","es":"Parte 1 — Salud general"},"fields":[{"key":"over_45","type":"yes_no","required":true,"label":{"en":"I am 45 years of age or older","es":"Tengo 45 años o más"}},{"key":"dm_q1","type":"yes_no","required":true,"sensitive":true,"label":{"en":"1. Problems with lungs, breathing, heart, blood, or a COVID-19 diagnosis?","es":"1. ¿Problemas de pulmones, respiración, corazón, sangre, o diagnóstico de COVID-19?"}},{"key":"dm_q3","type":"yes_no","required":true,"sensitive":true,"label":{"en":"3. Struggle to perform moderate exercise (for example walk 1.6 km / 1 mile in 14 minutes without distress)?","es":"3. ¿Le cuesta hacer ejercicio moderado (por ejemplo caminar 1.6 km en 14 minutos sin dificultad)?"}},{"key":"dm_q4","type":"yes_no","required":true,"sensitive":true,"label":{"en":"4. Problems with eyes, ears, nasal passages, or teeth?","es":"4. ¿Problemas de ojos, oídos, vías nasales o dientes?"}},{"key":"dm_q5","type":"yes_no","required":true,"sensitive":true,"label":{"en":"5. Surgery within the last 12 months?","es":"5. ¿Cirugía en los últimos 12 meses?"}},{"key":"dm_q6","type":"yes_no","required":true,"sensitive":true,"label":{"en":"6. Lost consciousness, migraines, seizures, stroke, or neurological problems?","es":"6. ¿Pérdida de conciencia, migrañas, convulsiones, derrame o problemas neurológicos?"}},{"key":"dm_q7","type":"yes_no","required":true,"sensitive":true,"label":{"en":"7. Treatment for psychological problems, panic attacks, or addiction?","es":"7. ¿Tratamiento por problemas psicológicos, ataques de pánico o adicción?"}},{"key":"dm_q8","type":"yes_no","required":true,"sensitive":true,"label":{"en":"8. Back problems, hernia, ulcers, or diabetes?","es":"8. ¿Problemas de espalda, hernia, úlceras o diabetes?"}},{"key":"dm_q9","type":"yes_no","required":true,"sensitive":true,"label":{"en":"9. Stomach/intestine problems or recent diarrhea?","es":"9. ¿Problemas de estómago/intestino o diarrea reciente?"}},{"key":"dm_q10","type":"yes_no","required":true,"sensitive":true,"label":{"en":"10. Currently taking prescription medications (other than birth control or anti-malarial)?","es":"10. ¿Toma medicamentos con receta (además de anticonceptivos o antimaláricos)?"}}]},{"id":"dm_boxes","title":{"en":"Part 2 — Detailed medical history","es":"Parte 2 — Historial médico detallado"},"fields":[{"key":"dm_box_A_1","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q1","op":"eq","value":"yes"},"label":{"en":"Box A: Chest surgery, heart surgery, or implantable device","es":"Casilla A: Cirugía de tórax/corazón o dispositivo implantable"}},{"key":"dm_box_A_2","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q1","op":"eq","value":"yes"},"label":{"en":"Box A: Asthma or severe allergies in the last 12 months","es":"Casilla A: Asma o alergias graves en los últimos 12 meses"}},{"key":"dm_box_A_3","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q1","op":"eq","value":"yes"},"label":{"en":"Box A: Heart condition (angina, heart failure, arrhythmia, etc.)","es":"Casilla A: Afección cardíaca (angina, insuficiencia, arritmia, etc.)"}},{"key":"dm_box_A_4","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q1","op":"eq","value":"yes"},"label":{"en":"Box A: Recurrent bronchitis, emphysema, or lung disease","es":"Casilla A: Bronquitis recurrente, enfisema o enfermedad pulmonar"}},{"key":"dm_box_A_5","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q1","op":"eq","value":"yes"},"label":{"en":"Box A: Symptoms that impair performance in the last 30 days","es":"Casilla A: Síntomas que limitan el rendimiento en los últimos 30 días"}},{"key":"dm_box_B_1","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q3","op":"eq","value":"yes"},"label":{"en":"Box B: Unable to walk 1.6 km (1 mile) in 14 minutes without distress","es":"Casilla B: No puede caminar 1.6 km en 14 minutos sin dificultad"}},{"key":"dm_box_B_2","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q3","op":"eq","value":"yes"},"label":{"en":"Box B: Chest pain, shortness of breath, or dizziness with exercise","es":"Casilla B: Dolor de pecho, falta de aire o mareo con ejercicio"}},{"key":"dm_box_C_1","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q4","op":"eq","value":"yes"},"label":{"en":"Box C: Sinus or ear surgery, or chronic sinus/ear problems","es":"Casilla C: Cirugía de senos/oídos o problemas crónicos"}},{"key":"dm_box_C_2","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q4","op":"eq","value":"yes"},"label":{"en":"Box C: Eye surgery or vision problems affecting diving","es":"Casilla C: Cirugía ocular o problemas de visión que afecten el buceo"}},{"key":"dm_box_C_3","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q4","op":"eq","value":"yes"},"label":{"en":"Box C: Active dental problems or recent oral surgery","es":"Casilla C: Problemas dentales activos o cirugía oral reciente"}},{"key":"dm_box_D_1","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q5","op":"eq","value":"yes"},"label":{"en":"Box D: Still healing from surgery in the last 12 months","es":"Casilla D: Aún sanando de cirugía en los últimos 12 meses"}},{"key":"dm_box_D_2","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q5","op":"eq","value":"yes"},"label":{"en":"Box D: Doctor advised delay of strenuous activity after surgery","es":"Casilla D: Médico indicó retrasar actividad intensa tras cirugía"}},{"key":"dm_box_E_1","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q6","op":"eq","value":"yes"},"label":{"en":"Box E: Head injury with loss of consciousness","es":"Casilla E: Traumatismo craneal con pérdida de conciencia"}},{"key":"dm_box_E_2","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q6","op":"eq","value":"yes"},"label":{"en":"Box E: Seizures, epilepsy, or stroke / TIA","es":"Casilla E: Convulsiones, epilepsia o derrame / AIT"}},{"key":"dm_box_E_3","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q6","op":"eq","value":"yes"},"label":{"en":"Box E: Recurrent severe migraines","es":"Casilla E: Migrañas graves recurrentes"}},{"key":"dm_box_F_1","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q7","op":"eq","value":"yes"},"label":{"en":"Box F: Anxiety, panic attacks, or PTSD under treatment","es":"Casilla F: Ansiedad, pánico o TEPT en tratamiento"}},{"key":"dm_box_F_2","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q7","op":"eq","value":"yes"},"label":{"en":"Box F: Depression or other psychological treatment","es":"Casilla F: Depresión u otro tratamiento psicológico"}},{"key":"dm_box_F_3","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q7","op":"eq","value":"yes"},"label":{"en":"Box F: Substance addiction treatment","es":"Casilla F: Tratamiento por adicción"}},{"key":"dm_box_G_1","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q8","op":"eq","value":"yes"},"label":{"en":"Box G: Back/spine problems, hernia, or chronic pain","es":"Casilla G: Problemas de espalda/columna, hernia o dolor crónico"}},{"key":"dm_box_G_2","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q8","op":"eq","value":"yes"},"label":{"en":"Box G: Ulcer, diabetes, or metabolic disease","es":"Casilla G: Úlcera, diabetes o enfermedad metabólica"}},{"key":"dm_box_G_3","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q9","op":"eq","value":"yes"},"label":{"en":"Box G: Stomach/intestine disease or recent severe diarrhea","es":"Casilla G: Enfermedad estómago/intestino o diarrea grave reciente"}},{"key":"dm_box_G_4","type":"checkbox","sensitive":true,"show_if":{"field":"dm_q10","op":"eq","value":"yes"},"label":{"en":"Box G: Prescription medication that may affect diving","es":"Casilla G: Medicamento con receta que pueda afectar el buceo"}},{"key":"dm_dental","type":"yes_no","required":true,"sensitive":true,"label":{"en":"Dental — Are you still healing or recovering from a recent dental or oral procedure?","es":"Dental — ¿Aún está sanando o recuperándose de un procedimiento dental/oral reciente?"}},{"key":"participant_statement","type":"checkbox","required":true,"label":{"en":"I answered all questions honestly and accept responsibility for any inaccurate answers.","es":"Respondí todas las preguntas con honestidad y acepto la responsabilidad por respuestas inexactas."}}]}]}',
    version = '3',
    updated_at = strftime('%s','now') * 1000
WHERE key = 'diver_medical';
